import{u as i,o as a,c as u,j as t,k as s,F as n,a8 as q,e as l,p as d}from"./chunks/framework.fPNBP_58.js";const c=["markdown-url"],m={"data-allow-mismatch":"",style:{display:"none"}},b=JSON.parse('{"title":"Climate Change Explorer for Tourism","description":"","frontmatter":{"layout":"page"},"headers":[],"params":{"narrative":"ccet-use-case-3","file":"https://gtif-austria.github.io/public-narratives/ccet-use-case-3.md","title":"Climate Change Explorer for Tourism"},"relativePath":"narratives/ccet-use-case-3.md","filePath":"narratives/[narrative].md"}'),h={name:"narratives/ccet-use-case-3.md"},_=Object.assign(h,{setup(p){const o=d(!0);o.value=!1;const{params:r}=i();return(g,e)=>(a(),u("div",null,[t("client-only",null,[t("eox-storytelling",{"show-nav":"","markdown-url":s(r).file,"show-hero-scroll-indicator":"","show-map-loading-indicator":"",class:"full-width",style:{transform:"translateY(calc(var(--vp-nav-height) - 2px))","margin-top":"calc(var(--vp-nav-height) * -1 - 90px + 48px)","margin-bottom":"var(--vp-nav-height)","--eox-storytelling-hero-height":"auto"}},null,8,c)]),t("div",m,[o.value?(a(),u(n,{key:0},[e[0]||(e[0]=q(' --- cover-image: https://raw.githubusercontent.com/GTIF-Austria/public-narratives/15b40e551592acfb70cc317f4d5ba64f88a36840/assets/MichaelaLandauer/CCETUC3Tourism-indicators-II-1791189337034.jpg domain: Climate Change &amp; Tourism provider: GeoVille,Austria Tourism --- <h1 id="climate-change-explorer-for-tourism" tabindex="-1">Climate Change Explorer for Tourism <a class="header-anchor" href="#climate-change-explorer-for-tourism" aria-label="Permalink to &quot;Climate Change Explorer for Tourism &lt;!--{ as=&quot;img&quot; mode=&quot;hero&quot; src=&quot;https://raw.githubusercontent.com/GTIF-Austria/public-narratives/15b40e551592acfb70cc317f4d5ba64f88a36840/assets/MichaelaLandauer/CCETUC3Tourism-indicators-II-1791189337034.jpg&quot; }--&gt;&quot;">​</a></h1><h3 id="use-case-3-tourism-indicators" tabindex="-1">Use Case 3 - Tourism Indicators <a class="header-anchor" href="#use-case-3-tourism-indicators" aria-label="Permalink to &quot;Use Case 3 - Tourism Indicators&quot;">​</a></h3><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Climate Change Explorer for Tourism (CCET) is a joint initiative by <a href="https://www.geoville.com/" target="_blank" rel="noreferrer"><strong>GeoVille</strong></a>, <a href="https://b2b.austria.info/de-at/" target="_blank" rel="noreferrer"><strong>Österreich Werbung</strong></a>, <a href="https://eox.at/" target="_blank" rel="noreferrer"><strong>EOX</strong></a> and <a href="https://www.brz.gv.at/" target="_blank" rel="noreferrer"><strong>BRZ</strong></a> within Digital Twin Austria (GTIF-AT EA), giving Austria&#39;s tourism regions a user-friendly picture of climate change impacts and hazards. This page looks at the third and final use case showcased in the tool: the impact of climate change on tourism metrics.</p><h2 id="what-use-case-3-is-about" tabindex="-1">What Use Case 3 is about <a class="header-anchor" href="#what-use-case-3-is-about" aria-label="Permalink to &quot;What Use Case 3 is about&quot;">​</a></h2><p>This use case combines climate indicators with tourism-related metrics, helping to interpret how climate change may already be affecting tourism in practice – arguably the question of most direct interest to destinations and tourism professionals.</p><p><strong>Explore the Tourism Indicators dataset <a href="https://gtif-austria.info/explore?indicator=tourism_uc3_correlation" target="_blank" rel="noreferrer">HERE</a>.</strong></p><h2 id="exploring-climate-indicators-for-sustainable-tourism-planning-and-development" tabindex="-1">Exploring Climate Indicators for sustainable tourism planning and development <a class="header-anchor" href="#exploring-climate-indicators-for-sustainable-tourism-planning-and-development" aria-label="Permalink to &quot;Exploring Climate Indicators for sustainable tourism planning and development &lt;!--{ as=&quot;eox-map&quot; mode=&quot;tour&quot; position=&quot;right&quot; }--&gt;&quot;">​</a></h2><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&lt;!--{ layers=&#39;[{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;cloudless-2025;:;EPSG:3857&quot;,&quot;title&quot;:&quot;EOxCloudless 2025&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/s2cloudless-2025_3857/default/g/{z}/{y}/{x}.jpeg&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ EOxCloudless 2025: &lt;a href=\\&quot;//s2maps.eu\\&quot; target=\\&quot;_blank\\&quot;&gt;Sentinel-2 cloudless - s2maps.eu&lt;/a&gt; by &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX IT Services GmbH&lt;/a&gt; (Contains modified Copernicus Sentinel data 2025) }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}},{&quot;type&quot;:&quot;VectorTile&quot;,&quot;declutter&quot;:true,&quot;properties&quot;:{&quot;id&quot;:&quot;tourism_uc3_correlation;:;2026-02-15T00:00:00Z;:;Tourism &amp; Climate Correlation Analysis;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Tourism &amp; Climate Correlation Analysis&quot;},&quot;source&quot;:{&quot;type&quot;:&quot;VectorTile&quot;,&quot;format&quot;:{&quot;type&quot;:&quot;MVT&quot;},&quot;url&quot;:&quot;https://eoapi.workspace.gtif-eox.hub-otc.eox.at/vector/collections/public.gtif_tourism_uc3_for_date/tiles/WebMercatorQuad/{z}/{x}/{y}?target_date=2026-02-15&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;},&quot;style&quot;:{&quot;variables&quot;:{&quot;prop&quot;:&quot;stays&quot;},&quot;tooltip&quot;:[{&quot;id&quot;:&quot;tourism_region&quot;,&quot;title&quot;:&quot;Tourism Region&quot;},{&quot;id&quot;:&quot;tourism_id&quot;,&quot;title&quot;:&quot;Tourism ID&quot;},{&quot;id&quot;:&quot;region_type&quot;,&quot;title&quot;:&quot;Region Type&quot;},{&quot;id&quot;:&quot;season&quot;,&quot;title&quot;:&quot;Season&quot;},{&quot;id&quot;:&quot;stays&quot;,&quot;title&quot;:&quot;Overnight Stays&quot;,&quot;decimals&quot;:0},{&quot;id&quot;:&quot;snow_depth_mean&quot;,&quot;title&quot;:&quot;Mean Snow Depth (m) &quot;,&quot;decimals&quot;:1},{&quot;id&quot;:&quot;max_temp_mean&quot;,&quot;title&quot;:&quot;Maximum Temperature (°C) &quot;,&quot;decimals&quot;:1},{&quot;id&quot;:&quot;precip_sum_mean&quot;,&quot;title&quot;:&quot;Mean Precipitation Sum (mm)&quot;,&quot;decimals&quot;:1}],&quot;fill-color&quot;:[&quot;case&quot;,[&quot;==&quot;,[&quot;get&quot;,&quot;stays&quot;],&quot;N/A&quot;],[128,128,128,0.25],[&quot;==&quot;,[&quot;coalesce&quot;,[&quot;get&quot;,&quot;stays&quot;],&quot;N/A&quot;],&quot;N/A&quot;],[0,0,0,0],[&quot;match&quot;,&quot;stays&quot;,&quot;stays&quot;,[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;get&quot;,&quot;stays&quot;],0],[&quot;-&quot;,10000,0]],0,[255,247,236,1],0.125,[254,232,200,1],0.25,[253,212,158,1],0.375,[253,187,132,1],0.5,[252,141,89,1],0.625,[239,101,72,1],0.75,[215,48,31,1],0.875,[179,0,0,1],1,[127,0,0,1]],&quot;snow_depth_mean&quot;,[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;get&quot;,&quot;snow_depth_mean&quot;],0],[&quot;-&quot;,0.5,0]],0,[247,252,253,1],0.125,[224,236,244,1],0.25,[191,211,230,1],0.375,[158,188,218,1],0.5,[140,150,198,1],0.625,[140,107,177,1],0.75,[136,65,157,1],0.875,[129,15,124,1],1,[77,0,75,1]],&quot;max_temp_mean&quot;,[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;get&quot;,&quot;max_temp_mean&quot;],-10],[&quot;-&quot;,35,-10]],0,[49,54,149,1],0.1,[69,117,180,1],0.2,[116,173,209,1],0.3,[171,217,233,1],0.4,[224,243,248,1],0.5,[255,255,191,1],0.6,[254,224,144,1],0.7,[253,174,97,1],0.8,[244,109,67,1],0.9,[215,48,39,1],1,[165,0,38,1]],&quot;precip_sum_mean&quot;,[&quot;interpolate&quot;,[&quot;linear&quot;],[&quot;/&quot;,[&quot;-&quot;,[&quot;get&quot;,&quot;precip_sum_mean&quot;],0],[&quot;-&quot;,50,0]],0,[255,255,229,1],0.125,[247,252,185,1],0.25,[217,240,163,1],0.375,[173,221,142,1],0.5,[120,198,121,1],0.625,[65,171,93,1],0.75,[35,132,67,1],0.875,[0,104,55,1],1,[0,69,41,1]],[128,128,128,1]]],&quot;stroke-color&quot;:&quot;black&quot;,&quot;stroke-width&quot;:1}},{&quot;type&quot;:&quot;Tile&quot;,&quot;properties&quot;:{&quot;id&quot;:&quot;overlay_bright;:;EPSG:3857&quot;,&quot;title&quot;:&quot;Overlay labels&quot;,&quot;visible&quot;:true},&quot;source&quot;:{&quot;type&quot;:&quot;XYZ&quot;,&quot;url&quot;:&quot;https://{a-e}.s2maps-tiles.eu/wmts/1.0.0/overlay_base_bright_3857/default/g/{z}/{y}/{x}.png&quot;,&quot;projection&quot;:&quot;EPSG:3857&quot;,&quot;attributions&quot;:&quot;{ Overlay: Data &amp;copy; &lt;a href=\\&quot;http://www.openstreetmap.org/copyright\\&quot; target=\\&quot;_blank\\&quot;&gt;OpenStreetMap&lt;/a&gt; contributors, Made with Natural Earth, Rendering &amp;copy; &lt;a href=\\&quot;//eox.at\\&quot; target=\\&quot;_blank\\&quot;&gt;EOX&lt;/a&gt; }&quot;,&quot;tileGrid&quot;:{&quot;tileSize&quot;:[256,256]}}}]&#39; zoom=&quot;7.2409990849716035&quot; center=[13.749999999999998,47.26880864150519] projection=&quot;&quot; animationOptions={duration:500}}--&gt;&quot;">​</a></h3><h4 id="tourism-indicators" tabindex="-1">Tourism Indicators <a class="header-anchor" href="#tourism-indicators" aria-label="Permalink to &quot;Tourism Indicators&quot;">​</a></h4><p>This dataset shows the tourism and climate correlation analysis - the extent to which climate-related trends, such as a decline in snow cover, already correlate with overnight stay figures. Daily precipitation sum, maximum temperature, and snow depth data are spatially aggregated to Austrian tourism destinations for the period 2023-2026 during winter (November-April) and summer (May-October) seasons.</p><h2 id="the-data-behind-it" tabindex="-1">The data behind it <a class="header-anchor" href="#the-data-behind-it" aria-label="Permalink to &quot;The data behind it&quot;">​</a></h2><p>Observed daily precipitation and maximum temperature come from <a href="https://data.hub.geosphere.at/dataset/spartacus-v2-1d-1km" target="_blank" rel="noreferrer">GeoSphere Austria&#39;s SPARTACUS v2.1 dataset</a> (a 1 km grid, daily since 1961). These are combined with snow depth data – the same <a href="https://data.hub.geosphere.at/dataset/snowgrid_cl-v2-1d-1km" target="_blank" rel="noreferrer">SNOWGRID-CL dataset</a> used in Use Case 2, considered only during the winter season (November to April) – and with a daily forecast of overnight stays supplied by Österreich Werbung at tourism-destination level. All three data streams are spatially aggregated to Austria&#39;s tourism destinations for the period 2023–2026 and linked together, resulting in a combined dataset of climate and tourism indicators covering both winter and summer seasons, on a daily basis, from 1 January 2023 to 15 February 2026.</p><h2 id="benefit-for-users" tabindex="-1">Benefit for users <a class="header-anchor" href="#benefit-for-users" aria-label="Permalink to &quot;Benefit for users&quot;">​</a></h2><ul><li><p>Tourism professionals can see, side by side, how day-to-day and season-to-season climate conditions track alongside actual and forecast visitor demand.</p></li><li><p>Early shifts in traveller behaviour – for instance, a mild winter coinciding with softer overnight-stay forecasts – can be identified sooner, rather than only after the season has ended.</p></li><li><p>Because the data spans both winter and summer, destinations can compare how climate sensitivity differs between seasons and plan sustainable, season-specific offerings accordingly.</p></li></ul>',16))],64)):l("",!0)])]))}});export{b as __pageData,_ as default};
